import functools

@functools.lru_cache(None)
def solve(state):
    # state is a sorted tuple of numbers
    # Check termination conditions
    # Condition (1): one number is larger than the sum of all others
    if len(state) > 0:
        total_sum = sum(state)
        for x in state:
            if x > total_sum - x:
                return len(state)

    # Condition (2): all numbers are 0
    if len(state) > 0 and all(x == 0 for x in state):
        return len(state)

    # Game cannot proceed if only 1 or 0 numbers are left
    if len(state) <= 1:
        return len(state)

    # Player A's turn to pick two indices x, y
    # A wants to maximize the result
    best_a = -float('inf')

    # Try all pairs to erase
    for i in range(len(state)):
        for j in range(i + 1, len(state)):
            # Player B's turn to choose between x+y and |x-y|
            # B wants to minimize the result
            x, y = state[i], state[j]

            # Option 1: x + y
            next_state_plus = sorted(list(state[:i] + state[i+1:j] + state[j+1:]) + [x + y])
            res_plus = solve(tuple(next_state_plus))

            # Option 2: |x - y|
            next_state_minus = sorted(list(state[:i] + state[i+1:j] + state[j+1:]) + [abs(x - y)])
            res_minus = solve(tuple(next_state_minus))

            best_b = min(res_plus, res_minus)
            best_a = max(best_a, best_b)

    return best_a

for n in range(1, 11):
    initial_state = tuple([1] * n)
    print(f"N={n}, result={solve(initial_state)}")

